  feedback_summary_student = 'Отзывы о лингвистическом университете сильно расходятся. Сильные стороны — переводческое и лингвистическое направления держат высокую планку, активная внеучебная жизнь (кружки, медиа, волонтёрство). Заметная и повторяющаяся критика — пренебрежительное отношение деканата к бюджетным студентам, ощущение падения общего уровня вуза по сравнению с прошлым, малая доля преподавателей, реально заинтересованных в обучении студентов.',
  feedback_positive_highlights = '{"сильная переводческая и лингвистическая школа","активная внеучебная жизнь и волонтёрство"}',
  feedback_negative_highlights = '{"пренебрежительное отношение деканата к бюджетникам","ощущение падения уровня вуза"}',
  feedback_based_on_count = 7, feedback_generated_at = now(), updated_at = now()
where name = 'Московский государственный лингвистический университет' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы преимущественно негативные. Основная и повторяющаяся критика — крайне неорганизованный учебный процесс, преобладание теории без практики на профильных предметах, устаревшее или полностью нерабочее оборудование, неуважительное и порой оскорбительное отношение отдельных преподавателей и методистов к студентам, плохие бытовые условия (нет кулеров, дорогая столовая). Есть отдельные положительные отклики о хороших преподавателях на экономическом факультете.',
  feedback_positive_highlights = '{"опытные преподаватели на отдельных непрофильных факультетах"}',
  feedback_negative_highlights = '{"устаревшее или нерабочее оборудование, нехватка практики","неуважительное отношение преподавателей и методистов","плохие бытовые условия"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Российский университет медицины Министерства здравоохранения Российской Федерации' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы о бывшем МГОУ, ныне Государственном университете просвещения, смешанные и сильно зависят от факультета. Плюсы — хороший преподавательский состав на многих направлениях, активная студенческая жизнь и площадки для самореализации. Критика — распространено мнение, что вуз даёт лишь базовые знания, а остальное студент должен добирать самостоятельно; качество обучения заметно неравномерно между факультетами.',
  feedback_positive_highlights = '{"активная студенческая жизнь","хороший преподавательский состав на ряде направлений"}',
  feedback_negative_highlights = '{"неравномерное качество обучения по факультетам","ощущение недостатка практических знаний, даваемых вузом"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Государственный университет просвещения' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Один из ведущих вузов страны по подготовке психологов, второй по востребованности выпускников-психологов после МГУ по отзывам работодателей. Студенты хвалят актуальную программу, практику с 1 курса, компетентных и доброжелательных преподавателей, отсутствие коррупции. Из критики — неравномерное отношение к работающим студентам на некоторых факультетах и отдельные жалобы на несправедливые оценки на экзаменах, а на дистанционном отделении программу проходят слишком поверхностно.',
  feedback_positive_highlights = '{"востребованность выпускников-психологов у работодателей","практика с 1 курса, актуальная программа","отсутствие коррупции"}',
  feedback_negative_highlights = '{"неравномерное отношение к работающим студентам","поверхностное обучение на дистанционном отделении"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Московский государственный психолого-педагогический университет' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Отзывы преимущественно положительные, вуз получил «зелёную метку» на портале отзывов абитуриентов. Хвалят требовательный, но хорошо подобранный преподавательский состав, свежий ремонт и хорошее материально-техническое обеспечение по сравнению с другими педагогическими вузами Москвы, насыщенную студенческую жизнь. Из критики — постоянные проблемы с расписанием на отдельных кафедрах, слабая практическая подготовка по некоторым направлениям, крайне высокий конкурс на бюджетные места.',
  feedback_positive_highlights = '{"хорошее материально-техническое обеспечение","требовательный и подготовленный преподавательский состав","насыщенная студенческая жизнь"}',
  feedback_negative_highlights = '{"проблемы с расписанием на отдельных кафедрах","слабая практическая подготовка по части направлений","высокий конкурс на бюджет"}',
  feedback_based_on_count = 7, feedback_generated_at = now(), updated_at = now()
where name = 'Московский городской педагогический университет' and city = 'Москва';
